 private function data(array $extra=[]): array {return array_merge(['submission_id'=>(string)\Illuminate\Support\Str::uuid(),'kind'=>'inspection','name'=>'TEST Nimal Perera','phone'=>'0771234567','vehicle'=>'Toyota Prius','registration_number'=>'TEST-9001','service'=>'Hybrid battery care','message'=>'TEST battery warning','contact_consent'=>true,'source_page'=>'contact.html'],$extra);}
 private function req(array $data=[],string $method='POST'): Request {$r=Request::create('http://localhost/website-api/requests',$method,$data,[],[],['REMOTE_ADDR'=>'127.0.0.1','HTTP_ORIGIN'=>'https://site.example','HTTP_ACCEPT'=>'application/json']);$r->setLaravelSession($this->session);$this->app->instance('request',$r);$r->setUserResolver(fn($guard=null)=>$this->actor);return $r;}
 private function received(array $extra=[]): object {(new CcsWebsiteIntake)->receive($this->data($extra),'https://site.example','127.0.0.1');return DB::table('ccs_website_requests')->orderByDesc('id')->first();}
 public function test_website_forms_save_all_request_types_without_creating_business_records(): void {foreach(['inspection','quote','contact','warranty','complaint'] as $type)$this->received(['kind'=>$type]);self::assertSame(5,DB::table('ccs_website_requests')->count());self::assertSame(2,DB::table('customers')->count());self::assertSame(2,DB::table('repair_jobs')->count());}
 public function test_duplicate_submission_is_idempotent_and_changed_data_is_rejected(): void {$s=new CcsWebsiteIntake;$d=$this->data();$a=$s->receive($d,'https://site.example','1');$b=$s->receive($d,'https://site.example','1');self::assertSame($a['reference'],$b['reference']);self::assertTrue($b['duplicate']);self::assertSame(1,DB::table('ccs_website_requests')->count());$d['message']='changed';$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$s->receive($d,'https://site.example','1');}
 public function test_consent_is_required_and_mass_assignment_is_ignored(): void {$s=new CcsWebsiteIntake;$d=$this->data(['status'=>'resolved','customer_id'=>2,'internal_notes'=>'injected']);$s->receive($d,'https://site.example','1');$r=DB::table('ccs_website_requests')->first();self::assertSame('new',$r->status);self::assertNull($r->customer_id);self::assertNull($r->internal_notes);$this->expectException(\Illuminate\Validation\ValidationException::class);$s->receive($this->data(['contact_consent'=>false]),'https://site.example','1');}
 public function test_honeypot_and_past_preferred_date_are_rejected(): void {foreach([['website'=>'spam'],['preferred_date'=>'2020-01-01']] as $bad){try{$this->received($bad);self::fail('Bad input accepted');}catch(\Illuminate\Validation\ValidationException){self::assertSame(0,DB::table('ccs_website_requests')->count());}}}
 public function test_public_middleware_allows_exact_origin_and_adds_cors_to_validation_errors(): void {$m=new \App\Http\Middleware\CcsWebsitePublic;$r=$this->req();$out=$m->handle($r,fn()=>throw \Illuminate\Validation\ValidationException::withMessages(['phone'=>'Bad phone']));self::assertSame(422,$out->getStatusCode());self::assertSame('https://site.example',$out->headers->get('Access-Control-Allow-Origin'));self::assertFalse($out->headers->has('Access-Control-Allow-Credentials'));$r->headers->set('Origin','https://evil.example');$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$m->handle($r,fn()=>response('bad'));}
 public function test_public_http_submit_without_session_csrf_and_preflight_work(): void {$kernel=$this->app->make(\Illuminate\Contracts\Http\Kernel::class);$r=$this->req($this->data());$out=$kernel->handle($r);self::assertSame(201,$out->getStatusCode(),$out->getContent());self::assertSame(1,DB::table('ccs_website_requests')->count());self::assertFalse($out->headers->has('Set-Cookie'));$r=$this->req([],'OPTIONS');self::assertSame(204,$kernel->handle($r)->getStatusCode());}
