 public function test_lookup_requires_matching_owned_serial_and_never_returns_private_fields(): void {(new CcsWebsiteSettings)->save(['lookup_mode'=>'plate_serial']);$c=new CcsWebsitePublicController;$no=$c->lookup($this->req(['plate'=>'TEST-4821','serial'=>'OTHER-SERIAL']),new CcsWebsiteSettings);self::assertSame(404,$no->getStatusCode());$yes=$c->lookup($this->req(['plate'=>'TEST 4821','serial'=>'TEST-ABS-001']),new CcsWebsiteSettings);self::assertSame(200,$yes->getStatusCode());$text=$yes->getContent();foreach(['PRIVATE Kasun','PRIVATE ADDRESS','PRIVATE COMPLAINT','OTHER-SERIAL','OTHER-JOB','total_lkr','phone','customer_id'] as $secret)self::assertStringNotContainsString($secret,$text);self::assertStringContainsString('TEST-ABS-001',$text);}
