 public function test_staff_review_requires_confirmation_time_and_rejects_stale_updates(): void {$item=$this->received();$c=new CcsWebsiteInboxController;try{$c->update($this->req(['version'=>1,'status'=>'confirmed']),$item->id);self::fail('Missing time accepted');}catch(\Illuminate\Validation\ValidationException){}$c->update($this->req(['version'=>1,'status'=>'reviewing','internal_notes'=>'STAFF ONLY']),$item->id);self::assertSame(2,DB::table('ccs_website_requests')->first()->version);$this->expectException(\Illuminate\Validation\ValidationException::class);$c->update($this->req(['version'=>1,'status'=>'resolved']),$item->id);}
