 public function test_developer_requires_explicit_public_lookup_consent(): void {$c=new CcsWebsiteSettingsController;$dev=(object)['id'=>1,'active'=>true,'password'=>Hash::make('TEST_DEVELOPER_PASSWORD')];$r=$this->req(['current_password'=>'TEST_DEVELOPER_PASSWORD','lookup_mode'=>'plate_only']);$r->attributes->set('ccs_developer',$dev);$c->developerSave($r,new CcsWebsiteSettings);self::assertSame('disabled',(new CcsWebsiteSettings)->values()['lookup_mode']);$r=$this->req(['current_password'=>'TEST_DEVELOPER_PASSWORD','lookup_mode'=>'plate_only','ack_public'=>1]);$r->attributes->set('ccs_developer',$dev);$c->developerSave($r,new CcsWebsiteSettings);self::assertSame('plate_only',(new CcsWebsiteSettings)->values()['lookup_mode']);}
 public function test_new_admin_views_render_customer_input_as_text(): void {$item=$this->received(['name'=>'<script>alert(1)</script>']);mkdir($this->temp.'/views/ccs',0700,true);mkdir($this->temp.'/views/developer',0700,true);file_put_contents($this->temp.'/views/ccs/layout.blade.php',"@yield('content')");file_put_contents($this->temp.'/views/developer/layout.blade.php',"@yield('content')");$this->app['view']->getFinder()->setPaths([$this->temp.'/views',dirname(__DIR__,2).'/resources/views']);$r=$this->req([], 'GET');$html=(new CcsWebsiteInboxController)->show($r,$item->id)->render();self::assertStringNotContainsString('<script>alert(1)</script>',$html);self::assertStringContainsString('&lt;script&gt;',$html);self::assertStringContainsString('Create Job Card',$html);$dev=view('developer.website',['developer'=>(object)['name'=>'TEST'],'values'=>(new CcsWebsiteSettings)->values()])->render();self::assertStringContainsString('plate_only',$dev);}
