 }
 public function test_database_viewer_rejects_staff_and_unlisted_tables_and_masks_secrets(): void {
  view()->share('errors',new \Illuminate\Support\ViewErrorBag);config(['auth.guards.ccs_developer'=>['driver'=>'session','provider'=>'users']]);$c=new \App\Http\Controllers\CcsDatabaseViewerController;
  $r=$this->req([]);try{$c->index($r);self::fail('Staff accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(403,$e->getStatusCode());}
  Schema::create('viewer_secrets',function($t){$t->id();$t->string('name');$t->string('password');$t->text('payload');});DB::table('viewer_secrets')->insert(['name'=>'<script>bad</script>','password'=>'DO_NOT_EXPOSE','payload'=>'PRIVATE_SESSION']);
  foreach(['test-data','calendar','team'] as $n)$this->app['router']->get('/dev-test/'.$n,fn()=>null)->name('developer.'.$n);$this->app['router']->get('/developer/database',fn()=>null)->name('developer.database');$this->app['router']->getRoutes()->refreshNameLookups();
  $r=$this->req(['table'=>'viewer_secrets']);$r->attributes->set('ccs_developer',(object)['active'=>1]);$response=$c->index($r);$html=$response->getContent();self::assertStringNotContainsString('DO_NOT_EXPOSE',$html);self::assertStringNotContainsString('PRIVATE_SESSION',$html);self::assertStringContainsString('&lt;script&gt;bad&lt;/script&gt;',$html);
  $r=$this->req(['table'=>'customers; DROP TABLE customers']);$r->attributes->set('ccs_developer',(object)['active'=>1]);try{$c->index($r);self::fail('Invalid table accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(404,$e->getStatusCode());}self::assertSame(2,DB::table('customers')->count());
 }
 private function dbChangesSetup():array {
  (require dirname(__DIR__,2).'/database/migrations/2026_10_29_000026_create_developer_database_controls.php')->up();
  if(!Schema::hasTable('ccs_developer_accounts'))Schema::create('ccs_developer_accounts',function($t){$t->id();$t->string('name');$t->string('email');$t->boolean('active');});
  DB::table('ccs_developer_accounts')->insert(['id'=>99,'name'=>'TEST Developer','email'=>'developer@example.test','active'=>true]);
  $actor=(object)['id'=>99,'name'=>'TEST Developer','active'=>true,'can_manage_accounts'=>true,'password'=>Hash::make('TEST-only-password-123'),'access_version'=>1];
  return [new \App\Services\CcsDeveloperDatabaseChanges,$actor];
 }
 private function dbRequest($actor,array $d=[]):Request {$r=$this->req($d);$r->attributes->set('ccs_developer',$actor);return $r;}
 private function dbGrant(int $id=99):void {DB::table('ccs_developer_db_permissions')->insert(['developer_account_id'=>$id,'can_add'=>true,'can_edit'=>true,'can_delete'=>true]);}
 private function dbFields():array{return ['kind'=>'contact','name'=>'TEST Kasun Silva','phone'=>'0770000000','message'=>'TEST request for maintenance','reason'=>'Correcting dummy test details'];}
 public function test_db_changes_start_denied_even_for_team_administrator():void {[$s,$a]=$this->dbChangesSetup();self::assertSame(['add'=>false,'edit'=>false,'delete'=>false],$s->grant($a));$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$s->preview($this->dbRequest($a,$this->dbFields()),'add');}
 public function test_db_add_edit_delete_are_audited_without_changing_business_records():void {
  [$s,$a]=$this->dbChangesSetup();$this->dbGrant();$before=DB::table('customers')->count();$p=$s->preview($this->dbRequest($a,$this->dbFields()+['customer_id'=>1,'status'=>'converted','contact_consent'=>true]),'add');$id=$s->commit($p,$a,'TEST-BACKUP');$row=$s->row($id);self::assertSame('new',$row->status);self::assertNull($row->customer_id);self::assertSame(0,$row->contact_consent);self::assertSame('94770000000',$row->phone);
  $fields=$this->dbFields();$fields['name']='TEST Edited Customer';$p=$s->preview($this->dbRequest($a,$fields),'edit',$id);$s->commit($p,$a,'TEST-BACKUP-2');self::assertSame('TEST Edited Customer',$s->row($id)->name);
  $p=$s->preview($this->dbRequest($a,['reason'=>'Remove dummy enquiry only']),'delete',$id);$s->commit($p,$a,'TEST-BACKUP-3');self::assertFalse(DB::table('ccs_website_requests')->where('id',$id)->exists());self::assertSame(3,DB::table('ccs_developer_db_changes')->count());self::assertSame($before,DB::table('customers')->count());$log=DB::table('ccs_developer_db_changes')->latest('id')->first();self::assertStringContainsString('TEST Edited Customer',$log->before_json);self::assertNull($log->after_json);
 }
 public function test_db_linked_requests_cannot_be_edited_or_deleted():void {[$s,$a]=$this->dbChangesSetup();$this->dbGrant();$i=$this->received();DB::table('ccs_website_requests')->where('id',$i->id)->update(['repair_job_id'=>1]);$this->expectException(\Illuminate\Validation\ValidationException::class);$s->preview($this->dbRequest($a,['reason'=>'Remove dummy enquiry only']),'delete',$i->id);}
 public function test_db_stale_preview_and_replays_cannot_overwrite_newer_rows():void {[$s,$a]=$this->dbChangesSetup();$this->dbGrant();$i=$this->received();$p=$s->preview($this->dbRequest($a,$this->dbFields()),'edit',$i->id);DB::table('ccs_website_requests')->where('id',$i->id)->update(['message'=>'New staff note']);try{$s->commit($p,$a,'TEST');self::fail('Stale write accepted');}catch(\Illuminate\Validation\ValidationException){}self::assertSame('New staff note',$s->row($i->id)->message);$p=$s->preview($this->dbRequest($a,$this->dbFields()),'add');$s->commit($p,$a,'TEST');$this->expectException(\Illuminate\Validation\ValidationException::class);$s->commit($p,$a,'TEST');}
