  try{$c->preview($this->dbRequest($a,$this->dbFields()+['action'=>'add','current_password'=>'WRONG']),$s);self::fail('Wrong password accepted');}catch(\Illuminate\Validation\ValidationException){}self::assertSame(0,DB::table('ccs_website_requests')->count());
