 }
 public function test_db_failed_backup_prevents_changes():void {
  [$s,$a]=$this->dbChangesSetup();$this->dbGrant();$p=$s->preview($this->dbRequest($a,$this->dbFields()),'add');$this->session->put('ccs_database_change',$p);config(['queue.default'=>'sync']);$backups=$this->createMock(CcsSqliteBackup::class);$backups->expects(self::once())->method('create')->willThrowException(new \RuntimeException('TEST backup failed'));$lock=fopen($this->temp.'/lock','c');flock($lock,LOCK_SH);$r=$this->dbRequest($a,['current_password'=>'TEST-only-password-123','operation_id'=>$p['operation_id'],'confirm'=>true,'phrase'=>'ADD NEW']);$r->attributes->set('ccs_database_lock',$lock);
  try{(new \App\Http\Controllers\CcsDeveloperDatabaseChangesController)->apply($r,$s,$backups);self::fail('Backup error ignored');}catch(\Illuminate\Validation\ValidationException){}finally{flock($lock,LOCK_UN);fclose($lock);}self::assertSame(0,DB::table('ccs_website_requests')->count());self::assertFalse(app(\Illuminate\Contracts\Foundation\MaintenanceMode::class)->active());
 }
 public function test_db_permissions_require_team_admin_and_history_cannot_be_changed():void {[$s,$a]=$this->dbChangesSetup();$a->can_manage_accounts=false;$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);(new \App\Http\Controllers\CcsDeveloperDatabaseChangesController)->savePermissions($this->dbRequest($a,['developer_id'=>99,'can_delete'=>true,'current_password'=>'TEST-only-password-123']),$s);}
 public function test_db_controls_views_render_and_escape_values():void {
  [$changes,$developer]=$this->dbChangesSetup();$this->dbGrant();config(['auth.guards.ccs_developer'=>['driver'=>'session','provider'=>'users']]);view()->share('errors',new \Illuminate\Support\ViewErrorBag);
  foreach(['test-data','calendar','team','home','logout'] as $n)$this->app['router']->get('/dev-test/'.$n,fn()=>null)->name('developer.'.$n);
  foreach(['','change','preview','apply','permissions','permissions.save','history'] as $n)$this->app['router']->get('/dev-db/'.str_replace('.','/',$n),fn()=>null)->name('developer.database'.($n?'.'.$n:''));$this->app['router']->getRoutes()->refreshNameLookups();
  $fields=$this->dbFields();$fields['name']='<script>TEST</script>';$plan=$changes->preview($this->dbRequest($developer,$fields),'add');
  foreach(['database-change'=>['row'=>null,'action'=>'add'],'database-change-review'=>['plan'=>$plan],'database-permissions'=>['accounts'=>DB::table('ccs_developer_accounts')->get(),'grants'=>DB::table('ccs_developer_db_permissions')->get()->keyBy('developer_account_id')],'database-history'=>['events'=>DB::table('ccs_developer_db_changes')->selectRaw('*, NULL as developer_name')->paginate(20)]] as $name=>$data){$html=view('developer.'.$name,$data+['developer'=>$developer])->render();self::assertStringNotContainsString('<script>TEST</script>',$html);self::assertNotEmpty($html);}
 }
 public function test_database_routes_use_developer_guard_and_post_only_apply():void {
  (new \App\Providers\CcsDatabaseViewerServiceProvider($this->app))->boot();$routes=$this->app['router']->getRoutes();$routes->refreshNameLookups();$route=$routes->getByName('developer.database.apply');self::assertSame(['POST'],$route->methods());self::assertContains(\App\Http\Middleware\CcsDeveloperAccess::class,$route->gatherMiddleware());self::assertContains(\App\Http\Middleware\CcsDatabaseLock::class,$route->gatherMiddleware());self::assertNotNull($routes->getByName('developer.database'));
 }
